pub fn int(self: RenameAt2Flags) u32 {
            var flags: u32 = 0;
            _ = &flags;
            if (comptime Environment.isMac) {
                if (self.exchange) {
                    flags = (flags | c.RENAME_SWAP);
                }
                if (self.exclude) {
                    flags = (flags | c.RENAME_EXCL);
                }
                if (self.nofollow) {
                    flags = (flags | c.RENAME_NOFOLLOW_ANY);
                }
            } else {
                if (comptime Environment.isLinux) {
                    if (self.exchange) {
                        flags = (flags | c.RENAME_EXCHANGE);
                    }
                    if (self.exclude) {
                        flags = (flags | c.RENAME_NOREPLACE);
                    }
                }
            }
            return flags;
    }
};

