        switch (Environment.os) {
.linux => {
_ = std.os.linux.fallocate(fd, 0, (if (comptime @typeInfo(@TypeOf((if (comptime @typeInfo(@TypeOf(offset)) == .@"enum") cp_cast_int(i32, @intFromEnum(offset)) else cp_cast_int(i32, offset)))) == .@"enum") cp_cast_int(i64, @intFromEnum((if (comptime @typeInfo(@TypeOf(offset)) == .@"enum") cp_cast_int(i32, @intFromEnum(offset)) else cp_cast_int(i32, offset)))) else cp_cast_int(i64, (if (comptime @typeInfo(@TypeOf(offset)) == .@"enum") cp_cast_int(i32, @intFromEnum(offset)) else cp_cast_int(i32, offset)))), len);
},
.mac => {

},
else => {

},
}
}

pub fn dlopen(filename: [:0]const u8, flags: std.c.RTLD) ?*anyopaque {
        if (comptime Environment.isWindows) {
            return bun.windows.LoadLibraryA(filename);
        }
        return std.c.dlopen(filename, flags);
}

pub fn dlsymImpl(handle: ?*anyopaque, name: [:0]const u8) ?*anyopaque {
        if (comptime Environment.isWindows) {
            return bun.windows.GetProcAddressA(handle, name);
        } else {
            if (comptime (Environment.isMac or Environment.isLinux)) {
                return std.c.dlsym(handle, name.ptr);
            }
        }
        _ = @compileError("dlsym unimplemented for this target");
}

pub fn dlsymWithHandle(comptime Type: type, comptime name: [:0]const u8, comptime handle_getter: *const fn () ?*anyopaque) ?Type {
        if (comptime (@typeInfo(Type) != .pointer)) {
            _ = @compileError((("dlsym must be a pointer type (e.g. ?const *fn()). Received " ++ @typeName(Type)) ++ "."));
        }
        if (dlsymImpl(@call(bun.callmod_inline, handle_getter, .{}), name)) |ptr| {
            _ = &ptr;
            return bun.cast(Type, ptr);
        }
        return null;
}
